import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.DXa1R37q.js";const m=JSON.parse('{"title":"Upgrades and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"guides/upgrades-and-recovery.md","filePath":"guides/upgrades-and-recovery.md","lastUpdated":1792970147000}'),n={name:"guides/upgrades-and-recovery.md"};function i(d,e,c,s,l,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="upgrades-and-recovery" tabindex="-1">Upgrades and recovery <a class="header-anchor" href="#upgrades-and-recovery" aria-label="Permalink to &quot;Upgrades and recovery&quot;">​</a></h1><p>After an upgrade, validate each enabled domain. Confirm canonical counts, inspect errors, and rebuild disposable caches only after canonical validation succeeds.</p><p>For a stale revision, fetch current state, compare the competing change, and retry with the new revision. For lease contention, inspect the current owner evidence and wait for the owner to exit. Do not delete a live lease.</p><p>For a corrupt or incompatible cache, remove the domain DB, WAL, and SHM files or choose the documented rebuild path. Canonical files recreate it. Under <code>stale_policy: fail</code>, run the domain validation tool to make the rebuild explicit. Searchable library users can call <code>runtime.store.validate()</code>; MCP users may temporarily choose a reviewed <code>rebuild</code> policy.</p><p>Repository Store recovers authenticated journals while acquiring a lease. If recovery fails closed, preserve the transaction directory and reported evidence before manual changes. A modified or ambiguous journal needs operator review.</p><p>Treat unsupported runtime or filesystem errors as deployment constraints. Move the operation to a supported Linux runtime and local filesystem; do not rewrite canonical data.</p>',6)])])}const h=a(n,[["render",i]]);export{m as __pageData,h as default};
